def emit_8byte_zeroes(count):
    if count == 0:
        return
    bytes_to_fill = count * 8
    print(f"  .fill {bytes_to_fill}")

def dump_page_table_as_asm(pt):
    """Print the page table in a way suitable for consumption by assembler"""
    trd = {} # I use dictionary to traverse entries in sorted order
    for addr, ptes in pt['pages'].items():
        zero_counter = 0
